'''Inventory intake helpers for parsing and tagging batch text.'''


def clean_line(line):
    return ' '.join(line.strip().split())


def split_row(row):
    parts = row.split(':', 1)
    if len(parts) == 2:
        return [parts[0].strip(), parts[1].strip()]
    return [parts[0].strip(), '0']


def parse_batch(text):
    rows = []
    for raw in text.splitlines():
        line = clean_line(raw)
        if not line:
            continue
        if line.startswith('#'):
            continue
        cut = -1
        for sep in (':', '|', ';'):
            idx = line.find(sep)
            if idx != -1 and (cut == -1 or idx < cut):
                cut = idx
        if cut == -1:
            rows.append([line, '0'])
        else:
            rows.append([line[:cut].strip(), line[cut + 1:].strip()])
    return rows


def tag_scheme(rows):
    tags = []
    for pair in rows:
        mark = 'std'
        if pair[1].isdigit() and int(pair[1]) >= 10:
            mark = 'bulk'
        tags.append(pair[0] + '#' + mark)
    return tags

